SELECT id, 'betriebswasserpumpe', '{"anlagenteil":"betriebswasserpumpe"}'::jsonb, NULL, 'Betriebswasserpumpe', 4, '{"inspektion_intervall":"6 Monate","inspektion_umfang":"visuelle Prüfung des Schaltspiels auf Betriebsfähigkeit und der Dichtheit","wartung_intervall":"1 Jahr","wartung_umfang":"Probelauf: Vor, während bzw. nach dem Probelauf sind zu prüfen: die elektrische Absicherung der Pumpenanlage nach VDE-Vorschriften; Vordruck des Membranbehälters (falls vorhanden); Dichtheit der Gleitringdichtung der Pumpe; Funktion des Rückflussverhinderers; Pumpen- und Strömungsgeräusche; Dichtheit der Anlage und Armaturen; Sauberkeit der Anlage; Korrosion der Anlagenteile","hinweis":null}'::jsonb, '\hline \multirow[t]{2}{*}{Betriebswasserpumpe} & Inspektion & visuelle Prüfung des Schaltspiels auf Betriebsfähigkeit und der Dichtheit & 6 Monate \\
\hline & Wartung & \begin{tabular}{l}
Probelauf: \\
Vor, während bzw. nach dem Probelauf sind zu prüfen: \\
- die elektrische Absicherung der Pumpenanlage nach VDE-Vorschriften \\
- Vordruck des Membranbehälters (falls vorhanden) \\
- Dichtheit der Gleitringdichtung der Pumpe \\
- Funktion des Rückflussverhinderers \\
- Pumpen- und Strömungsgeräusche \\
- Dichtheit der Anlage und Armaturen \\
- Sauberkeit der Anlage \\
- Korrosion der Anlagenteile
\end{tabular} & 1 Jahr \\' FROM regulation_tables WHERE standard_code = 'DIN-1989-1' AND edition = '2002' AND table_code = 'TAB5'
