SELECT id, 'rueckflussverhinderer', '{"anlagenteil":"rueckflussverhinderer"}'::jsonb, NULL, 'Rückflussverhinderer', 10, '{"inspektion_intervall":"1 Jahr","inspektion_umfang":"Zur Prüfung des dichten Abschlusses ist die Rohrleitung in Fließrichtung vor dem Rückflussverhinderer abzusperren. Durch Öffnen der Prüfvorrichtung, die sich auf der Eingangsseite des Rückflussverhinderers befindet, wird festgestellt, ob Wasser ausfließt. Dabei wird vorausgesetzt, dass die Verbrauchsleitungen nach dem Rückflussverhinderer mit Wasser gefüllt sind. Der Abschluss ist dicht, wenn aus den Prüfstutzen kein Wasser ausfließt.","wartung_intervall":null,"wartung_umfang":null,"hinweis":null}'::jsonb, '\hline Rückflussverhinderer & Inspektion & Zur Prüfung des dichten Abschlusses ist die Rohrleitung in Fließrichtung vor dem Rückflussverhinderer abzusperren. Durch Öffnen der Prüfvorrichtung, die sich auf der Eingangsseite des Rückflussverhinderers befindet, wird festgestellt, ob Wasser ausfließt. Dabei wird vorausgesetzt, dass die Verbrauchsleitungen nach dem Rückflussverhinderer mit Wasser gefüllt sind. Der Abschluss ist dicht, wenn aus den Prüfstutzen kein Wasser ausfließt. & 1 Jahr \\' FROM regulation_tables WHERE standard_code = 'DIN-1989-1' AND edition = '2002' AND table_code = 'TAB5'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
